FuncDef.Code:
//-------------------------------------------------------------------------------
// main
//-------------------------------------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = convertFragCoordsToUv(fragCoord);

    vec4 thisPassOutput = texture(iChannel0, uv);
    vec4 prevPassOutput = texture(iChannel1, uv);

    float step = 1.0/float(renderer_historyLength);

    vec4 col =  thisPassOutput * (1. - step);

    col += prevPassOutput * step;

    col.a = 1.0;

    // output to screen
    fragColor = col;
}
